<script setup>
import { onMounted, ref } from 'vue'
import { api, errorMessage } from '../services/api'
import { useFeedbackStore } from '../stores/feedback'
const feedback=useFeedbackStore();const warnings=ref([]);const loading=ref(true)
async function load(){loading.value=true;try{warnings.value=(await api.get('/admin/warnings')).data.warnings}catch(e){feedback.show(errorMessage(e),'error')}finally{loading.value=false}}
async function ignore(item){if(!await feedback.confirm('Ignorar este aviso? Ele deixará de aparecer na lista.'))return;try{await api.post(`/admin/warnings/${encodeURIComponent(item.key)}/ignore`,{});await load();feedback.show('Aviso ignorado.')}catch(e){feedback.show(errorMessage(e),'error')}}
async function ignoreAll(){if(!warnings.value.length||!await feedback.confirm(`Ignorar todos os ${warnings.value.length} avisos pendentes?`, 'Ignorar todos os avisos'))return;try{const {data}=await api.post('/admin/warnings/ignore-all',{});warnings.value=[];feedback.show(`${data.ignored} avisos ignorados.`)}catch(e){feedback.show(errorMessage(e),'error')}}
onMounted(load)
</script>
<template><div class="page"><div class="page-head"><div><h1>Avisos</h1><p>Dados de clientes que precisam de atenção.</p></div><div class="d-flex align-center ga-3"><v-btn v-if="warnings.length" color="warning" variant="tonal" prepend-icon="mdi-eye-off-outline" @click="ignoreAll">Ignorar todos</v-btn><v-chip size="large" color="warning">{{warnings.length}} pendentes</v-chip></div></div><v-progress-linear v-if="loading" indeterminate/><v-row v-else><v-col v-for="item in warnings" :key="item.key" cols="12" md="6"><v-card class="soft-card pa-5"><div class="d-flex ga-4"><v-avatar color="warning" variant="tonal"><v-icon>mdi-alert-outline</v-icon></v-avatar><div class="flex-grow-1"><div class="text-h6 font-weight-bold">{{item.title}}</div><div class="text-body-2 text-medium-emphasis mt-1">{{item.detail}}</div><div class="mt-4"><b>{{item.customer_name}}</b><div class="text-caption">{{item.customer_company||'Sem empresa'}} · {{item.customer_email||'Sem email'}}</div></div><div class="d-flex ga-2 mt-4"><v-btn :to="`/admin/utilizadores/${item.entity_id}`" color="primary" variant="tonal">Corrigir dados</v-btn><v-btn variant="text" @click="ignore(item)">Ignorar</v-btn></div></div></div></v-card></v-col></v-row><div v-if="!loading&&!warnings.length" class="empty-state"><v-icon size="64" color="success">mdi-check-circle-outline</v-icon><div class="text-h5 font-weight-bold mt-4">Tudo em ordem</div><p>Não existem avisos por resolver.</p></div></div></template>
